function MillstoneTenteringScrewMaker.init() MillstoneTenteringScrewMaker.ironStock=18; MillstoneTenteringScrewMaker.bronzeStock=14; MillstoneTenteringScrewMaker.woodStock=10; MillstoneTenteringScrewMaker.leatherStock=8; MillstoneTenteringScrewMaker.silverStock=8; MillstoneTenteringScrewMaker.goldStock=6; MillstoneTenteringScrewMaker.jewelStock=4; MillstoneTenteringScrewMaker.pearlStock=4; MillstoneTenteringScrewMaker.productStock={}; MillstoneTenteringScrewMaker.buildings={}; MillstoneTenteringScrewMaker.maker=nil; MillstoneTenteringScrewMaker.activeMaking={}; MillstoneTenteringScrewMaker.totalProducts=0; MillstoneTenteringScrewMaker.dayTimer=0; print("[MillstoneTenteringScrewMaker] Royal Millstone Tentering Screw Maker System initialized (6 products, 4 buildings)") end
function MillstoneTenteringScrewMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneTenteringScrewMaker.maker={name=n or ("Vijačnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vijačnik najet: %s (spretnost: %d)",MillstoneTenteringScrewMaker.maker.name,s),"success") end; return true end
function MillstoneTenteringScrewMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneTenteringScrewMaker.build(id) local ok,e=MillstoneTenteringScrewMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneTenteringScrewMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneTenteringScrewMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneTenteringScrewMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneTenteringScrewMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneTenteringScrewMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneTenteringScrewMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneTenteringScrewMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneTenteringScrewMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneTenteringScrewMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneTenteringScrewMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneTenteringScrewMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneTenteringScrewMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneTenteringScrewMaker.buildings==0 then return false,"Potrebna vijačna delavnica" end; if not MillstoneTenteringScrewMaker.maker then return false,"Potreben vijacnik" end; return true end
function MillstoneTenteringScrewMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneTenteringScrewMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneTenteringScrewMaker.ironStock=MillstoneTenteringScrewMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneTenteringScrewMaker.bronzeStock=MillstoneTenteringScrewMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneTenteringScrewMaker.woodStock=MillstoneTenteringScrewMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneTenteringScrewMaker.leatherStock=MillstoneTenteringScrewMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneTenteringScrewMaker.silverStock=MillstoneTenteringScrewMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneTenteringScrewMaker.goldStock=MillstoneTenteringScrewMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneTenteringScrewMaker.jewelStock=MillstoneTenteringScrewMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneTenteringScrewMaker.pearlStock=MillstoneTenteringScrewMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneTenteringScrewMaker.maker then t=math.max(1,t-math.floor(MillstoneTenteringScrewMaker.maker.skill/13)) end; table.insert(MillstoneTenteringScrewMaker.activeMaking,{id="millstonetenteringscrew_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneTenteringScrewMaker.completeMaking(m) local q=1.0+(MillstoneTenteringScrewMaker.getQualityBonus()/100); if MillstoneTenteringScrewMaker.maker then q=q+(MillstoneTenteringScrewMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneTenteringScrewMaker.productStock[m.productType]=(MillstoneTenteringScrewMaker.productStock[m.productType] or 0)+m.quantity; MillstoneTenteringScrewMaker.totalProducts=MillstoneTenteringScrewMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneTenteringScrewMaker.maker then MillstoneTenteringScrewMaker.maker.itemsMade=MillstoneTenteringScrewMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneTenteringScrewMaker.maker.skill=math.min(100,MillstoneTenteringScrewMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vijak izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonetenteringscrew.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneTenteringScrewMaker.update(dt) if not _G.state then return end; MillstoneTenteringScrewMaker.dayTimer=MillstoneTenteringScrewMaker.dayTimer+dt; if MillstoneTenteringScrewMaker.dayTimer>=30 then MillstoneTenteringScrewMaker.dayTimer=0; for i=#MillstoneTenteringScrewMaker.activeMaking,1,-1 do local m=MillstoneTenteringScrewMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneTenteringScrewMaker.completeMaking(m); table.remove(MillstoneTenteringScrewMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneTenteringScrewMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneTenteringScrewMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneTenteringScrewMaker.getStats() return {ironStock=MillstoneTenteringScrewMaker.ironStock,bronzeStock=MillstoneTenteringScrewMaker.bronzeStock,woodStock=MillstoneTenteringScrewMaker.woodStock,leatherStock=MillstoneTenteringScrewMaker.leatherStock,silverStock=MillstoneTenteringScrewMaker.silverStock,goldStock=MillstoneTenteringScrewMaker.goldStock,jewelStock=MillstoneTenteringScrewMaker.jewelStock,pearlStock=MillstoneTenteringScrewMaker.pearlStock,productStock=MillstoneTenteringScrewMaker.productStock,numBuildings=#MillstoneTenteringScrewMaker.buildings,hasMaker=MillstoneTenteringScrewMaker.maker~=nil,makerName=MillstoneTenteringScrewMaker.maker and MillstoneTenteringScrewMaker.maker.name or "—",makerSkill=MillstoneTenteringScrewMaker.maker and MillstoneTenteringScrewMaker.maker.skill or 0,activeMaking=#MillstoneTenteringScrewMaker.activeMaking,totalProducts=MillstoneTenteringScrewMaker.totalProducts} end
